/**
 * One screen-full of state: license, project list, the script being edited,
 * live run output and the agent conversation. Everything observable is a
 * StateFlow so Compose can collect it directly; everything mutating runs
 * through small methods.
 */
class AppViewModel(app: Application) : AndroidViewModel(app) {

    private val licenseManager = LicenseManager(app, BuildConfig.LICENSE_PUBKEY)
    val licenseState: StateFlow<LicenseManager.LicenseState> = licenseManager.state

    private val workspace = Workspace.from(app)

    data class Project(val name: String, val dir: File)

    private val _projects = MutableStateFlow<List<Project>>(emptyList())
    val projects: StateFlow<List<Project>> = _projects.asStateFlow()

    private val _selected = MutableStateFlow<Project?>(null)
    val selected: StateFlow<Project?> = _selected.asStateFlow()

    /** Which tab of the editor is active: Python source, Node source or an npx command. */
    val editorMode = MutableStateFlow(RuntimeKind.PYTHON)
    val editorModeFlow: StateFlow<RuntimeKind> = editorMode.asStateFlow()

    private val _script = MutableStateFlow("")
    val script: StateFlow<String> = _script.asStateFlow()

    /** The npx command line (package + arguments) for the NPX editor tab. */
    val npxCommand = MutableStateFlow("cowsay@1.4.0 Привет, PocketRun!")
    val npxCommandFlow: StateFlow<String> = npxCommand.asStateFlow()

    sealed interface RunState {
        data object Idle : RunState
        data object Running : RunState
        data class Finished(val exitCode: Int, val durationMs: Long) : RunState
        data class Failed(val message: String) : RunState
    }

    data class OutputLine(val stream: OutputStream, val text: String)

    private val _runState = MutableStateFlow<RunState>(RunState.Idle)
    val runState: StateFlow<RunState> = _runState.asStateFlow()

    private val _output = MutableStateFlow<List<OutputLine>>(emptyList())
    val output: StateFlow<List<OutputLine>> = _output.asStateFlow()

    private var handle: ExecutionHandle? = null

    private val runListener = object : OutputListener {
        override fun onOutput(stream: OutputStream, text: String) {
            _output.update { lines -> (lines + OutputLine(stream, text)).takeLast(MAX_OUTPUT_LINES) }
        }

        override fun onFinished(result: dev.pocketrun.runtime.ExecResult) {
            _runState.value = RunState.Finished(result.exitCode, result.durationMs)
        }

        override fun onFailed(error: Throwable) {
            _runState.value = RunState.Failed(error.message ?: error.javaClass.simpleName)
        }
    }

    // ---------------------------------------------------------------- runtimes

    val jsRuntime: JsRuntime by lazy {
        val boot = getApplication<Application>().assets.open("node/boot.js")
            .bufferedReader(Charsets.UTF_8).use { it.readText() }
        JsRuntime(boot, workspace)
    }

    val npxRuntime: NpxRuntime by lazy { NpxRuntime(jsRuntime, workspace) }

    // ---------------------------------------------------------------- agent

    /** One bubble / row in the agent conversation. */
    sealed interface AgentItem {
        data class User(val text: String) : AgentItem
        data class Assistant(val text: String) : AgentItem
        data class Tool(val name: String, val args: String, val result: String?) : AgentItem
        data class Error(val text: String) : AgentItem
        data class Info(val text: String) : AgentItem
    }

    private val _agentMessages = MutableStateFlow<List<AgentItem>>(emptyList())
    val agentMessages: StateFlow<List<AgentItem>> = _agentMessages.asStateFlow()

    private val _agentRunning = MutableStateFlow(false)
    val agentRunning: StateFlow<Boolean> = _agentRunning.asStateFlow()

    private val _llmConfig = MutableStateFlow(AgentSettings.read(app))
    val llmConfig: StateFlow<AgentSettings.Config> = _llmConfig.asStateFlow()

    /** Sessions: the opencode-style local session store. */
    val sessions = Sessions(workspace)

    private val _sessionList = MutableStateFlow<List<Sessions.SessionInfo>>(emptyList())
    val sessionList: StateFlow<List<Sessions.SessionInfo>> = _sessionList.asStateFlow()

    private val _currentSession = MutableStateFlow<Sessions.SessionInfo?>(null)
    val currentSession: StateFlow<Sessions.SessionInfo?> = _currentSession.asStateFlow()

    private val _todos = MutableStateFlow<List<Sessions.Todo>>(emptyList())
    val todos: StateFlow<List<Sessions.Todo>> = _todos.asStateFlow()

    /** A question the agent is blocked on, waiting for the user's answer. */
    data class PendingQuestion(
        val questions: List<OpenCodeTools.Question>,
        val answer: (String) -> Unit,
    )

    private val _pendingQuestion = MutableStateFlow<PendingQuestion?>(null)
    val pendingQuestion: StateFlow<PendingQuestion?> = _pendingQuestion.asStateFlow()

    /** Model catalog loaded from the configured server (GET /models). */
    private val _modelCatalog = MutableStateFlow<List<String>>(emptyList())
    val modelCatalog: StateFlow<List<String>> = _modelCatalog.asStateFlow()

    private val _modelCatalogState = MutableStateFlow<String?>(null)
    val modelCatalogState: StateFlow<String?> = _modelCatalogState.asStateFlow()

    /** Open tabs — each tab is its own agent session (browser-style). */
    private val _openTabs = MutableStateFlow<List<Sessions.SessionInfo>>(emptyList())
    val openTabs: StateFlow<List<Sessions.SessionInfo>> = _openTabs.asStateFlow()

    /** A mutating tool call the agent is blocked on in manual confirm mode. */
    data class PendingApproval(val tool: String, val argsPreview: String, val respond: (Boolean) -> Unit)

    private val _pendingApproval = MutableStateFlow<PendingApproval?>(null)
    val pendingApproval: StateFlow<PendingApproval?> = _pendingApproval.asStateFlow()

    /** Live counters of the running turn: rounds done and when it started. */
    private val _agentSteps = MutableStateFlow(0)
    val agentSteps: StateFlow<Int> = _agentSteps.asStateFlow()

    private val _turnStartedAt = MutableStateFlow(0L)
    val turnStartedAt: StateFlow<Long> = _turnStartedAt.asStateFlow()

    /** Last user prompt, for the retry button. */
    @Volatile
    private var lastPrompt: String? = null

    private val agentExecutor: ExecutorService =
        Executors.newSingleThreadExecutor { r -> Thread(r, "pocketrun-agent").apply { isDaemon = true } }

    private val ioExecutor: ExecutorService =
        Executors.newSingleThreadExecutor { r -> Thread(r, "pocketrun-io").apply { isDaemon = true } }

    private val agentCancelled = AtomicBoolean(false)

    fun canUseAgent(): Boolean =
        (licenseState.value as? LicenseManager.LicenseState.Active)?.canUseAgent == true

    fun saveLlmConfig(config: AgentSettings.Config) {
        AgentSettings.save(getApplication(), config)
        _llmConfig.value = config
    }

    /** GET {baseUrl}/models — the Zen catalog for the Zen preset. */
    fun fetchModelCatalog(baseUrl: String, apiKey: String) {
        _modelCatalogState.value = "загрузка…"
        ioExecutor.execute {
            try {
                val models = LlmClient.models(baseUrl, apiKey)
                _modelCatalog.value = models
                _modelCatalogState.value = if (models.isEmpty()) "сервер не вернул моделей" else null
            } catch (t: Throwable) {
                _modelCatalog.value = emptyList()
                _modelCatalogState.value = t.message ?: t.javaClass.simpleName
            }
        }
    }

    fun clearAgentChat() {
        if (_agentRunning.value) return
        _agentMessages.value = emptyList()
        _todos.value = emptyList()
        _pendingQuestion.value = null
    }

    fun refreshSessions() {
        _sessionList.value = sessions.list()
    }

    private fun projectName(): String? = _selected.value?.name

    /** Loads a session into the chat without the running-guard (startup, tabs). */
    private fun showSession(id: String) {
        val session = sessions.load(id) ?: return
        _currentSession.value = session.info
        _todos.value = session.todos
        _agentMessages.value = historyToItems(session.messages)
    }

    /** Remembers the active tab and open tabs for the next app launch. */
    private fun persistAgentUi() {
        AgentSettings.saveUiState(getApplication(), _currentSession.value?.id, _openTabs.value.map { it.id })
    }

    /** `/new` — starts a fresh session for the current project. */
    fun newSession() {
        if (_agentRunning.value) return
        val session = sessions.create(project = projectName(), title = null, model = _llmConfig.value.model)
        _currentSession.value = session.info
        _agentMessages.value = emptyList()
        _todos.value = emptyList()
        registerTab(session.info)
        refreshSessions()
        persistAgentUi()
    }

    /** Resumes a stored session: history and todos come back into the chat. */
    fun openSession(id: String) {
        if (_agentRunning.value) return
        showSession(id)
        refreshSessions()
        persistAgentUi()
    }

    fun forkSession(id: String) {
        if (_agentRunning.value) return
        sessions.fork(id)?.let { child ->
            _currentSession.value = child.info
            _todos.value = child.todos
            _agentMessages.value = historyToItems(child.messages)
            registerTab(child.info)
        }
        refreshSessions()
        persistAgentUi()
    }

    fun renameSession(id: String, title: String) {
        sessions.rename(id, title)
        val updated = sessions.list().firstOrNull { it.id == id }
        if (updated != null) {
            _openTabs.value = _openTabs.value.map { if (it.id == id) updated else it }
            if (_currentSession.value?.id == id) _currentSession.value = updated
        }
        refreshSessions()
        persistAgentUi()
    }

    fun deleteSession(id: String) {
        sessions.delete(id)
        _openTabs.value = _openTabs.value.filterNot { it.id == id }
        if (_currentSession.value?.id == id) {
            val next = _openTabs.value.firstOrNull()
            if (next != null) showSession(next.id) else {
                _currentSession.value = null
                _agentMessages.value = emptyList()
                _todos.value = emptyList()
            }
        }
        refreshSessions()
        persistAgentUi()
    }

    /** `opencode export` analog: writes the session to opencode-data/exports/. */
    fun exportSession(id: String) {
        val path = sessions.export(id)
        _agentMessages.update {
            it + AgentItem.Info(
                if (path != null) "Сессия сохранена: $path"
                else "Не удалось экспортировать сессию",
            )
        }
    }

    private fun historyToItems(messages: JSONArray): List<AgentItem> {
        val items = mutableListOf<AgentItem>()
        for (i in 0 until messages.length()) {
            val m = messages.optJSONObject(i) ?: continue
            when (m.optString("role")) {
                "user" -> m.optString("content").takeIf { it.isNotBlank() }?.let { items += AgentItem.User(it) }
                "assistant" -> {
                    m.optString("content").takeIf { it.isNotBlank() }?.let { items += AgentItem.Assistant(it) }
                    val calls = m.optJSONArray("tool_calls")
                    if (calls != null) {
                        for (c in 0 until calls.length()) {
                            val fn = calls.optJSONObject(c)?.optJSONObject("function") ?: continue
                            items += AgentItem.Tool(fn.optString("name"), fn.optString("arguments").take(120), "")
                        }
                    }
                }
            }
        }
        return items
    }

    fun sendToAgent(text: String) {
        val prompt = text.trim()
        if (prompt.isEmpty() || _agentRunning.value) return

        // Chat commands, opencode-style.
        when (prompt) {
            "/new" -> {
                newSession()
                _agentMessages.update { it + AgentItem.Info("Новая сессия${projectName()?.let { " для проекта $it" } ?: ""}.") }
                return
            }
            "/init" -> {
                if (!requireConfigured()) return
                _agentMessages.update { it + AgentItem.User("/init") }
                runAgentTurn(
                    "Create an AGENTS.md file in the current project root: briefly describe the project " +
                        "(look at the files first) and add short, useful rules for future agents working in it. " +
                        "Keep it under 30 lines. Reply with a one-line summary.",
                )
                return
            }
            "/skills" -> {
                val found = dev.pocketrun.agent.opencode.Skills(workspace).discover(_selected.value?.dir)
                _agentMessages.update {
                    it + AgentItem.Info(
                        if (found.isEmpty()) "Навыков не найдено. Создайте свой: папка .opencode/skills/<имя>/SKILL.md в проекте с frontmatter name и description (или попросите агента — он умеет создавать навыки сам)."
                        else "Навыки:\n" + found.joinToString("\n") { s -> "• ${s.name}${if (s.global) " (глобальный)" else ""} — ${s.description}" },
                    )
                }
                return
            }
            "/help" -> {
                _agentMessages.update {
                    it + AgentItem.Info(
                        "Команды: /new — новая сессия · /init — создать AGENTS.md · /skills — список навыков · /help — эта справка.\n\n" +
                            "Навыки: создайте .opencode/skills/<имя>/SKILL.md (frontmatter: name, description) — агент подхватит и сможет загружать; глобальные — workspace/opencode/skills/.\n" +
                            "Инструкции: AGENTS.md в проекте + глобальный opencode/AGENTS.md, фолбэк CLAUDE.md; список файлов/URL — в opencode/opencode.json (\"instructions\").\n" +
                            "GitHub: ⚙ → GitHub (PAT с правами repo, workflow) — агент сможет создавать репозитории, Actions-раннеры (ubuntu-latest, там работают npm и opencode), следить за запусками и забирать логи/артефакты.\n" +
                            "Подтверждения и лимит раундов: ⚙ → «Подтверждения» и «Раундов на ход».\n" +
                            "Файл агенту: кнопка 📎 — файл копируется в проект и отправляется агенту.\n" +
                            "Остановка: ⏹ — ход прерывается, но сессия и история сохраняются.",
                    )
                }
                return
            }
        }

        if (!requireConfigured()) return
        lastPrompt = prompt
        _agentMessages.update { it + AgentItem.User(prompt) }
        runAgentTurn(prompt)
    }

    /** Re-runs the last prompt (shown next to errors). */
    fun retryLast() {
        val p = lastPrompt ?: return
        if (_agentRunning.value || p.isEmpty()) return
        if (!requireConfigured()) return
        _agentMessages.update { it + AgentItem.User("$p (повтор)") }
        runAgentTurn(p)
    }

    private fun requireConfigured(): Boolean {
        if (!canUseAgent()) {
            _agentMessages.update { it + AgentItem.Error("Агент доступен на плане Pro — активируйте Pro-лицензию.") }
            return false
        }
        val config = _llmConfig.value
        if (!config.isReady) {
            _agentMessages.update { it + AgentItem.Info("Сначала настройте модель: базовый URL и имя модели (кнопка ⚙ над чатом). API-ключ не нужен для локальных серверов; для Zen — бесплатный ключ с opencode.ai/auth.") }
            return false
        }
        return true
    }

    private fun runAgentTurn(userText: String) {
        val config = _llmConfig.value
        if (!config.isReady) return
        _agentRunning.value = true
        agentCancelled.set(false)
        _agentSteps.value = 0
        _turnStartedAt.value = System.currentTimeMillis()
        val turnStart = _turnStartedAt.value

        agentExecutor.execute {
            val projectDir = _selected.value?.dir
            val tools = OpenCodeTools(workspace, jsRuntime, npxRuntime, projectDir, config.githubToken)
            val agent = OpenCodeAgent(
                workspace, tools, { LlmClient(config) }, projectDir,
                maxSteps = config.safeMaxSteps,
                askMode = config.confirmMode == AgentSettings.MODE_ASK,
                hasGitHub = config.hasGitHub,
            )

            // The session this turn belongs to; create one on demand.
            val session = _currentSession.value?.let { sessions.load(it.id) }
                ?: sessions.create(project = projectName(), title = null, model = config.model)
            registerTab(session.info)

            // Question tool: block this thread until the user answers in the UI.
            tools.questionAsker = { questions ->
                val latch = CountDownLatch(1)
                var answer: String? = null
                _pendingQuestion.value = PendingQuestion(questions) { text ->
                    answer = text
                    _pendingQuestion.value = null
                    latch.countDown()
                }
                if (latch.await(10, TimeUnit.MINUTES)) {
                    answer ?: "(нет ответа)"
                } else {
                    _pendingQuestion.value = null
                    "(ответа не последовало)"
                }
            }

            // Manual mode: mutating tool calls wait for a tap in the UI.
            if (config.confirmMode == AgentSettings.MODE_MANUAL) {
                tools.toolApprover = { name, argsJson ->
                    val latch = CountDownLatch(1)
                    var approved = false
                    _pendingApproval.value = PendingApproval(name, argsJson.take(300)) { ok ->
                        approved = ok
                        _pendingApproval.value = null
                        latch.countDown()
                    }
                    if (!latch.await(10, TimeUnit.MINUTES)) {
                        _pendingApproval.value = null
                        false
                    } else {
                        approved
                    }
                }
            }

            tools.onTodos = { list ->
                session.todos = list
                _todos.value = list
            }
            tools.todos = session.todos

            agent.cancelled = agentCancelled.get()
            val newHistory = agent.run(userText, session.messages) { event ->
                when (event) {
                    is OpenCodeAgent.Event.AssistantText ->
                        _agentMessages.update { it + AgentItem.Assistant(event.text) }
                    is OpenCodeAgent.Event.ToolStart -> {
                        _agentSteps.value = _agentSteps.value + 1
                        _agentMessages.update { it + AgentItem.Tool(event.name, event.args, null) }
                    }
                    is OpenCodeAgent.Event.ToolDone ->
                        _agentMessages.update { items ->
                            val idx = items.indexOfLast { it is AgentItem.Tool && it.result == null && it.name == event.name }
                            if (idx >= 0) items.toMutableList().also { list -> list[idx] = (list[idx] as AgentItem.Tool).copy(result = event.result) }
                            else items + AgentItem.Tool(event.name, "", event.result)
                        }
                    is OpenCodeAgent.Event.Question ->
                        _agentMessages.update { it + AgentItem.Info("агент ждёт ответа на вопрос…") }
                    is OpenCodeAgent.Event.Todos ->
                        _todos.value = event.todos
                    is OpenCodeAgent.Event.Failed -> {
                        _agentMessages.update { it + AgentItem.Error(event.message) }
                        // Zen refuses keyless requests with 403 even for free
                        // models — tell the user where the free key lives.
                        if (config.isZen && "403" in event.message) {
                            _agentMessages.update {
                                it + AgentItem.Info(
                                    "Zen требует ключ даже для бесплатных моделей — получите его бесплатно на opencode.ai/auth " +
                                        "(кнопка ⚙ над чатом). Бесплатные модели не расходуют кредиты.",
                                )
                            }
                        }
                    }
                }
            }

            // Persist the turn: history, todos, auto-title from the first
            // message. Runs even after cancellation — memory is preserved.
            session.messages = newHistory
            session.info.model = config.model
            if (session.info.title == "Новая сессия") {
                val firstUser = firstUserText(newHistory) ?: userText
                val auto = firstUser.replace('\n', ' ').trim().take(40).let { if (it.length == 40) it + "…" else it }
                if (auto.isNotBlank()) session.info.title = auto
            }
            sessions.save(session)
            _currentSession.value = session.info
            refreshSessions()
            persistAgentUi()
            val secs = (System.currentTimeMillis() - turnStart) / 1000
            if (_agentSteps.value > 0 || agentCancelled.get()) {
                _agentMessages.update {
                    it + AgentItem.Info("⏱ раундов: ${_agentSteps.value} · время: ${secs}с · сессия сохранена")
                }
            }
            _agentRunning.value = false
        }
    }

    // ---------------------------------------------------------------- tabs

    private fun registerTab(info: Sessions.SessionInfo) {
        _openTabs.update { tabs -> if (tabs.any { it.id == info.id }) tabs.map { if (it.id == info.id) info else it } else tabs + info }
    }

    /** Opens (or switches to) a session tab. */
    fun switchTab(id: String) {
        if (_agentRunning.value) return
        showSession(id)
        val info = _sessionList.value.firstOrNull { it.id == id }
            ?: _openTabs.value.firstOrNull { it.id == id }
            ?: sessions.load(id)?.info
            ?: return
        registerTab(info)
        refreshSessions()
        persistAgentUi()
    }

    /** A fresh tab with its own new session. */
    fun newTab() {
        if (_agentRunning.value) return
        newSession() // registers the tab and persists itself
    }

    /** Closes the active tab and shows the neighbour (or an empty chat). */
    fun closeCurrentTab() {
        if (_agentRunning.value) return
        val current = _currentSession.value ?: return
        val tabs = _openTabs.value
        val idx = tabs.indexOfFirst { it.id == current.id }
        _openTabs.value = tabs.filterNot { it.id == current.id }
        val next = tabs.getOrNull(idx + 1) ?: tabs.getOrNull(idx - 1)
        if (next != null) {
            showSession(next.id)
        } else {
            _currentSession.value = null
            _agentMessages.value = emptyList()
            _todos.value = emptyList()
        }
        persistAgentUi()
    }

    // ---------------------------------------------------------------- files

    /**
     * Sends a file to the agent: copies it into the project's attachments/
     * folder and starts a turn so the agent can work with it (read/bash).
     */
    fun attachFile(uri: android.net.Uri) {
        if (_agentRunning.value) return
        val resolver = getApplication<Application>().contentResolver
        val name = runCatching {
            resolver.query(uri, null, null, null, null)?.use { c ->
                val idx = c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                if (idx >= 0 && c.moveToFirst()) c.getString(idx) else null
            }
        }.getOrNull() ?: "file-${System.currentTimeMillis()}.bin"
        val safe = name.replace(Regex("[^\\p{L}\\p{N}._-]"), "_").ifEmpty { "file.bin" }
        val dir = File(_selected.value?.dir ?: workspace.root, "attachments").apply { mkdirs() }
        val target = File(dir, safe)
        val bytes = runCatching {
            resolver.openInputStream(uri)?.use { ins -> target.outputStream().use { ins.copyTo(it) } }
            target.length()
        }.getOrNull()
        if (bytes == null) {
            _agentMessages.update { it + AgentItem.Error("Не удалось прочитать файл $name") }
            return
        }
        val rel = workspace.relativeTo(target)
        if (!canUseAgent() || !_llmConfig.value.isReady) {
            _agentMessages.update { it + AgentItem.Info("Файл сохранён: $rel ($bytes байт). Настройте модель — и агент сможет с ним работать.") }
            return
        }
        lastPrompt = null // retry doesn't apply to attachments
        _agentMessages.update { it + AgentItem.User("📎 $rel ($bytes байт)") }
        runAgentTurn(
            "The user attached the file \"$rel\" ($bytes bytes) to the project. Inspect it (read the first lines if it is text) " +
                "and briefly describe what it is and what can be done with it, then wait for instructions.",
        )
    }

    private fun firstUserText(history: JSONArray): String? {
        for (i in 0 until history.length()) {
            val m = history.optJSONObject(i) ?: continue
            if (m.optString("role") == "user") {
                val c = m.optString("content")
                if (c.isNotBlank() && !c.startsWith("Create an AGENTS.md")) return c
            }
        }
        return null
    }

    fun cancelAgent() {
        agentCancelled.set(true)
        _pendingQuestion.value?.answer?.invoke("(отменено пользователем)")
        _pendingApproval.value?.respond?.invoke(false)
    }

    // ---------------------------------------------------------------- projects

    init {
        refreshProjects()
        if (_projects.value.isEmpty()) createProject("hello")
        restoreAgentUi()
    }

    /**
     * Brings the agent chat back after the app was closed: the tabs that were
     * open and the active session, with history and todos. First launch (no
     * saved UI state) continues the most recent session, like `opencode -c`.
     * If the user closed all tabs on purpose, the chat starts empty.
     */
    private fun restoreAgentUi() {
        val existing = sessions.list().associateBy { it.id }
        val ui = AgentSettings.readUiState(getApplication())
        when {
            ui != null && ui.openTabs.isNotEmpty() -> {
                _openTabs.value = ui.openTabs.mapNotNull { existing[it] }
                val activeId = ui.lastSessionId?.takeIf { existing.containsKey(it) }
                    ?: _openTabs.value.firstOrNull()?.id
                if (activeId != null) showSession(activeId)
            }
            ui == null -> {
                // nothing saved yet (first run after update): continue latest
                sessions.list().firstOrNull()?.let { latest ->
                    _openTabs.value = listOf(latest)
                    showSession(latest.id)
                }
            }
            else -> Unit // the user closed all tabs — keep the chat empty
        }
    }

    fun refreshProjects() {
        _projects.value = workspace.projects
            .listFiles { file -> file.isDirectory }
            .orEmpty()
            .map { Project(it.name, it) }
            .sortedBy { it.name.lowercase() }
    }

    fun createProject(rawName: String) {
        val name = rawName.trim()
        if (name.isEmpty()) return
        val dir = workspace.projectDir(name)
        val main = File(dir, "main.py")
        if (!main.isFile) main.writeText(DEFAULT_SCRIPT, Charsets.UTF_8)
        refreshProjects()
        _projects.value.firstOrNull { it.dir == dir }?.let { select(it) }
    }

    fun deleteProject(project: Project) {
        project.dir.deleteRecursively()
        if (_selected.value?.dir == project.dir) {
            _selected.value = null
            _script.value = ""
        }
        refreshProjects()
    }

    fun select(project: Project) {
        _selected.value = project
        loadScriptForMode()
    }

    fun setEditorMode(mode: RuntimeKind) {
        editorMode.value = mode
        if (_selected.value != null) loadScriptForMode()
    }

    private fun loadScriptForMode() {
        val project = _selected.value ?: return
        when (editorMode.value) {
            RuntimeKind.NODE -> {
                val jsFile = File(project.dir, "main.js")
                _script.value = jsFile.takeIf { it.isFile }?.readText(Charsets.UTF_8) ?: DEFAULT_JS_SCRIPT
            }
            else -> {
                _script.value = File(project.dir, "main.py")
                    .takeIf { it.isFile }
                    ?.readText(Charsets.UTF_8)
                    ?: DEFAULT_SCRIPT
            }
        }
    }

    /** Saves the editor content under the active mode's file name. */
    fun saveScript(text: String) {
        val project = _selected.value ?: return
        when (editorMode.value) {
            RuntimeKind.NODE -> File(project.dir, "main.js").writeText(text, Charsets.UTF_8)
            else -> File(project.dir, "main.py").writeText(text, Charsets.UTF_8)
        }
    }

    fun runtimeAvailable(): Boolean = when (editorMode.value) {
        RuntimeKind.NODE, RuntimeKind.NPX -> true
        else -> PythonRuntime.isAvailable()
    }

    fun runtimeVersion(): String? = when (editorMode.value) {
        RuntimeKind.NODE, RuntimeKind.NPX -> JsRuntime.VERSION
        else -> PythonRuntime.version()
    }

    fun runScript(text: String) {
        val project = _selected.value ?: return
        if (_runState.value is RunState.Running) return
        when (editorMode.value) {
            RuntimeKind.NODE -> {
                saveScript(text)
                _output.value = emptyList()
                _runState.value = RunState.Running
                handle = jsRuntime.execute(
                    ExecRequest(
                        kind = RuntimeKind.NODE,
                        target = File(project.dir, "main.js").absolutePath,
                        args = emptyList(),
                        cwd = project.dir,
                    ),
                    runListener,
                )
            }
            RuntimeKind.PYTHON -> {
                if (!PythonRuntime.isAvailable()) {
                    _runState.value = RunState.Failed("Python ещё запускается — попробуйте через пару секунд")
                    return
                }
                saveScript(text)
                _output.value = emptyList()
                _runState.value = RunState.Running
                handle = PythonRuntime.execute(
                    ExecRequest(
                        kind = RuntimeKind.PYTHON,
                        target = File(project.dir, "main.py").absolutePath,
                        args = emptyList(),
                        cwd = project.dir,
                    ),
                    runListener,
                )
            }
            RuntimeKind.NPX -> {
                // The npx tab runs through runNpxCommand with its own command line.
            }
        }
    }

    fun runNpxCommand(line: String) {
        if (_runState.value is RunState.Running) return
        val parsed = NpxRuntime.parseCommandLine(line)
        if (parsed == null) {
            _runState.value = RunState.Failed("Не удалось разобрать команду — ожидается «пакет[@версия] [аргументы]»")
            return
        }
        val (spec, args) = parsed
        _output.value = emptyList()
        _runState.value = RunState.Running
        handle = npxRuntime.execute(
            ExecRequest(
                kind = RuntimeKind.NPX,
                target = spec.name + (spec.version?.let { "@$it" } ?: ""),
                args = args,
                cwd = _selected.value?.dir ?: workspace.root,
            ),
            runListener,
        )
    }

    /**
     * Cancellation is cooperative: the interpreter finishes the current script
     * and the run is reported with exit code 130.
     */
    fun cancelRun() {
        handle?.cancel()
    }

    fun clearOutput() {
        _output.value = emptyList()
        _runState.value = RunState.Idle
    }

    fun activate(rawKey: String): Boolean = licenseManager.activate(rawKey)

    fun forgetLicense() = licenseManager.forget()

    companion object {
        private const val MAX_OUTPUT_LINES = 2_000

        val DEFAULT_SCRIPT = """
            import sys

            print("Привет из PocketRun!")
            print("Python:", sys.version.split()[0])

            for i in range(1, 6):
                print(f"{i} * {i} = {i * i}")

            print("Эта строка ушла в stderr.", file=sys.stderr)
            print("Готово.")
        """.trimIndent()

        val DEFAULT_JS_SCRIPT = """
            // Node-совместимый слой PocketRun: require/fs/timers/Buffer/http доступны.
            const os = require('os');

            console.log('Привет из Node-слоя PocketRun!');
            console.log('Платформа:', os.platform());

            [1, 2, 3, 4, 5].forEach(function (n) {
                console.log(n + ' * ' + n + ' = ' + n * n);
            });

            setTimeout(function () {
                console.log('Это напечатано из таймера через 300 мс.');
                console.log('Готово.');
            }, 300);
        """.trimIndent()
    }
}

package dev.pocketrun.agent.opencode

import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.js.JsRuntime
import dev.pocketrun.runtime.npm.NpxRuntime
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.net.HttpURLConnection
import java.net.URL

/**
 * The opencode tool set, with opencode's names and semantics: bash, edit,
 * write, read, list, glob, grep, apply_patch, todowrite, webfetch, skill and
 * question. Everything runs inside the workspace sandbox; the `question`
 * tool surfaces an interactive prompt in the chat UI.
 */
class OpenCodeTools(
    private val workspace: Workspace,
    jsRuntime: JsRuntime,
    npxRuntime: NpxRuntime,
    private val projectDir: File?,
    private val githubToken: String = "",
) {

    companion object {
        private const val MAX_READ = 32 * 1024
        private const val MAX_TOOL_OUTPUT = 16 * 1024
        private const val MAX_WEB = 24 * 1024
        private const val BASH_TIMEOUT_MS = 120_000L
    }

    private val shell = MiniShell(workspace, jsRuntime, npxRuntime)
    private val skills = Skills(workspace)

    /** Answers pending questions; set by the agent runner. */
    @Volatile
    var questionAsker: ((List<Question>) -> String)? = null

    /**
     * Manual confirmation gate: return false to refuse the tool call. Only
     * invoked for mutating tools (writes, edits, bash, github mutations);
     * reads always run. Set by the runner when the mode is "manual".
     */
    @Volatile
    var toolApprover: ((name: String, argsJson: String) -> Boolean)? = null

    /** Todo updates flow to the session and UI through this hook. */
    @Volatile
    var onTodos: ((List<Sessions.Todo>) -> Unit)? = null

    /** The current todo list; seeded from the session before each turn. */
    var todos: List<Sessions.Todo> = emptyList()

    data class Question(val header: String?, val question: String, val options: List<String>)

    fun definitions(): JSONArray = JSONArray().apply {
        fun tool(name: String, description: String, properties: JSONObject, required: List<String>) {
            put(
                JSONObject().apply {
                    put("type", "function")
                    put(
                        "function",
                        JSONObject().apply {
                            put("name", name)
                            put("description", description)
                            put(
                                "parameters",
                                JSONObject().apply {
                                    put("type", "object")
                                    put("properties", properties)
                                    put("required", JSONArray(required))
                                },
                            )
                        },
                    )
                },
            )
        }

        fun str(name: String, desc: String) = JSONObject().put("type", "string").put("description", desc)
        fun int(name: String, desc: String) = JSONObject().put("type", "integer").put("description", desc)
        fun bool(name: String, desc: String) = JSONObject().put("type", "boolean").put("description", desc)
        fun arr(name: String, desc: String, itemSchema: JSONObject = str("item", "")) =
            JSONObject().put("type", "array").put("items", itemSchema).put("description", desc)

        tool(
            "bash",
            "Execute a shell command in the sandboxed project directory. Available commands: ${MiniShell.COMMANDS.joinToString(", ")}. " +
                "python runs CPython 3.13 (stdlib only), node runs the Node-compatible layer, npx installs/runs pure-JS npm packages. " +
                "Supports quoting, && , | and > >> redirection. No git, no package managers other than npx.",
            JSONObject()
                .put("command", str("command", "the shell command to run"))
                .put("timeout", int("timeout", "optional timeout in milliseconds (max 120000)")),
            listOf("command"),
        )
        tool(
            "read",
            "Read a text file (max ${MAX_READ} chars). Supports optional offset (1-based line) and limit.",
            JSONObject()
                .put("filePath", str("filePath", "path relative to the project root"))
                .put("offset", int("offset", "1-based line number to start from"))
                .put("limit", int("limit", "number of lines to read")),
            listOf("filePath"),
        )
        tool(
            "write",
            "Create or overwrite a file with the given content. Parent directories are created automatically.",
            JSONObject()
                .put("filePath", str("filePath", "path relative to the project root"))
                .put("content", str("content", "full file content")),
            listOf("filePath", "content"),
        )
        tool(
            "edit",
            "Edit an existing file by replacing an exact string. oldString must be unique in the file unless replaceAll is true.",
            JSONObject()
                .put("filePath", str("filePath", "path relative to the project root"))
                .put("oldString", str("oldString", "the exact text to replace"))
                .put("newString", str("newString", "the replacement text"))
                .put("replaceAll", bool("replaceAll", "replace every occurrence")),
            listOf("filePath", "oldString", "newString"),
        )
        tool(
            "list",
            "List a directory of the project.",
            JSONObject().put("path", str("path", "directory path, '.' is the project root")),
            listOf("path"),
        )
        tool(
            "glob",
            "Find files by glob pattern (e.g. '**/*.py', 'src/**/*.js'), sorted by modification time.",
            JSONObject()
                .put("pattern", str("pattern", "glob pattern"))
                .put("path", str("path", "directory to search in, defaults to the project root")),
            listOf("pattern"),
        )
        tool(
            "grep",
            "Search file contents with a regular expression; returns 'path:line: text' matches.",
            JSONObject()
                .put("pattern", str("pattern", "regular expression"))
                .put("path", str("path", "directory to search in, defaults to the project root"))
                .put("include", str("include", "glob filter for file names, e.g. '*.py'")),
            listOf("pattern"),
        )
        tool(
            "apply_patch",
            "Apply a patch in the *** Begin Patch format with *** Add File / *** Update File (+- lines) / *** Move to / *** Delete File sections.",
            JSONObject().put("patchText", str("patchText", "the full patch text")),
            listOf("patchText"),
        )
        tool(
            "todowrite",
            "Create or update the session todo list. Replaces the whole list; statuses: pending, in_progress, completed.",
            JSONObject().put(
                "todos",
                arr(
                    "todos",
                    "the full todo list",
                    JSONObject().put("type", "object")
                        .put(
                            "properties",
                            JSONObject()
                                .put("id", str("id", "stable id"))
                                .put("content", str("content", "task text"))
                                .put("status", str("status", "pending | in_progress | completed")),
                        )
                        .put("required", JSONArray(listOf("content", "status"))),
                ),
            ),
            listOf("todos"),
        )
        tool(
            "webfetch",
            "Fetch an http(s) URL and return the page as plain text (HTML stripped), max ${MAX_WEB} chars.",
            JSONObject().put("url", str("url", "the URL to fetch")),
            listOf("url"),
        )
        tool(
            "skill",
            "Load a skill (a SKILL.md file) and return its full content. ${"\n"}${skills.availableSkillsXml(projectDir)}",
            JSONObject().put("name", str("name", "skill name to load")),
            listOf("name"),
        )
        tool(
            "question",
            "Ask the user questions with optional choices; use this to clarify requirements or offer directions.",
            JSONObject().put(
                "questions",
                arr(
                    "questions",
                    "one or more questions",
                    JSONObject().put("type", "object")
                        .put(
                            "properties",
                            JSONObject()
                                .put("header", str("header", "short header"))
                                .put("question", str("question", "the question text"))
                                .put("options", arr("options", "answer options", str("option", ""))),
                        )
                        .put("required", JSONArray(listOf("question"))),
                ),
            ),
            listOf("questions"),
        )
        tool(
            "github",
            "Work with GitHub through its REST API: repositories, files, and **GitHub Actions runners**. " +
                "Runners (runs-on: ubuntu-latest) are full Linux machines — there you can run npm packages, " +
                "opencode itself (npm i -g opencode-ai; opencode run \"…\"), compilers, tests — the heavy work " +
                "the mobile sandbox cannot do. Typical flow: repo_create → push (code + .github/workflows/run.yml " +
                "with `on: workflow_dispatch`) → dispatch → poll runs → logs → artifacts. " +
                "Ops: me; repo_list; repo_create{name,private,description?}; push{repo,files[{path,content}],message,branch?}; " +
                "file_get{repo,path,ref?}; workflow_create{repo,filename,yaml}; dispatch{repo,workflow,ref?}; " +
                "runs{repo,limit?}; logs{repo,run_id}; artifacts{repo,run_id?}; artifact_download{repo,artifact_id}; " +
                "api{method,path,body?} for anything else (PRs, issues, releases). " +
                "Requires a GitHub token in the app settings (⚙ → GitHub, scopes repo+workflow).",
            JSONObject()
                .put("op", str("op", "operation name, see the list above"))
                .put("repo", str("repo", "owner/name"))
                .put("name", str("name", "repo name (for repo_create)"))
                .put("private", bool("private", "create a private repo (repo_create)"))
                .put("description", str("description", "repo description (repo_create)"))
                .put("files", arr("files", "files to push", JSONObject().put("type", "object").put("properties", JSONObject().put("path", str("path", "")).put("content", str("content", ""))).put("required", JSONArray(listOf("path", "content")))))
                .put("message", str("message", "commit message (push)"))
                .put("branch", str("branch", "branch name (push/file_get)"))
                .put("path", str("path", "file path (file_get)"))
                .put("ref", str("ref", "git ref (file_get/dispatch)"))
                .put("filename", str("filename", "workflow file name, e.g. run.yml (workflow_create)"))
                .put("yaml", str("yaml", "workflow YAML content (workflow_create)"))
                .put("workflow", str("workflow", "workflow file name (dispatch)"))
                .put("run_id", JSONObject().put("type", "integer").put("description", "run id (logs/artifacts)"))
                .put("artifact_id", JSONObject().put("type", "integer").put("description", "artifact id (artifact_download)"))
                .put("limit", int("limit", "max runs to list"))
                .put("method", str("method", "HTTP method (api)"))
                .put("api_path", str("api_path", "REST path like /repos/o/n/pulls (api)"))
                .put("body", str("body", "JSON body (api)")),
            listOf("op"),
        )
    }

    /** Executes one tool call; never throws — errors come back as text. */
    fun execute(name: String, argsJson: String): String {
        return try {
            val args = JSONObject(argsJson.ifBlank { "{}" })
            // Manual confirmation gate: mutating tools ask the user first.
            val approver = toolApprover
            if (approver != null && !isReadOnly(name, args)) {
                if (!approver(name, argsJson)) return "(отклонено пользователем)"
            }
            when (name) {
                "bash" -> doBash(args)
                "read" -> doRead(args)
                "write" -> doWrite(args)
                "edit" -> doEdit(args)
                "list" -> doList(args)
                "glob" -> doGlob(args)
                "grep" -> doGrep(args)
                "apply_patch" -> doApplyPatch(args)
                "todowrite" -> doTodoWrite(args)
                "webfetch" -> doWebFetch(args)
                "skill" -> doSkill(args)
                "question" -> doQuestion(args)
                "github" -> doGitHub(args)
                else -> "unknown tool: $name"
            }
        } catch (t: Throwable) {
            "error: ${t.message ?: t.javaClass.simpleName}"
        }
    }

    /** True when the call cannot change anything (auto-approved in manual mode). */
    fun isReadOnly(name: String, args: JSONObject): Boolean = when (name) {
        "read", "list", "glob", "grep", "webfetch", "skill", "question", "todowrite" -> true
        "github" -> args.optString("op") in GitHubClient.READ_OPS
        else -> false
    }

    // ---------------------------------------------------------------- tools

    private fun base(): File = projectDir ?: workspace.root

    private fun doBash(args: JSONObject): String {
        val command = args.getString("command")
        val timeout = args.optLong("timeout", BASH_TIMEOUT_MS).coerceIn(1_000, BASH_TIMEOUT_MS)
        val r = shell.execute(command, base(), timeout)
        val out = buildString {
            append("exit code: ").append(r.exitCode).append('\n')
            if (r.output.isNotBlank()) append(r.output.trimEnd()).append('\n')
        }
        return out.trim().take(MAX_TOOL_OUTPUT)
    }

    private fun doRead(args: JSONObject): String {
        val f = resolve(args.getString("filePath")) ?: return "error: путь вне песочницы"
        if (!f.exists()) return "error: файл не найден: ${args.getString("filePath")}"
        if (f.isDirectory) return "error: это каталог, используйте list"
        val text = f.readText(Charsets.UTF_8)
        val offset = args.optInt("offset", 1).coerceAtLeast(1)
        val limit = args.optInt("limit", 0)
        val lines = text.lines()
        val from = (offset - 1).coerceIn(0, lines.size)
        val to = if (limit > 0) minOf(from + limit, lines.size) else lines.size
        val picked = lines.subList(from, to)
        val body = picked.joinToString("\n")
        return (body.take(MAX_READ) + if (body.length > MAX_READ) "\n… (обрезано)" else "")
            .ifEmpty { "(пустой файл)" }
    }

    private fun doWrite(args: JSONObject): String {
        val path = args.getString("filePath")
        if (path.isBlank()) return "error: пустой путь"
        val f = resolve(path) ?: return "error: путь вне песочницы"
        f.parentFile?.mkdirs()
        f.writeText(args.optString("content", ""), Charsets.UTF_8)
        return "wrote ${args.optString("content", "").length} chars to ${workspace.relativeTo(f)}"
    }

    private fun doEdit(args: JSONObject): String {
        val f = resolve(args.getString("filePath")) ?: return "error: путь вне песочницы"
        if (!f.isFile) return "error: файл не найден: ${args.getString("filePath")}"
        val old = args.getString("oldString")
        val new = args.optString("newString", "")
        if (old.isEmpty()) return "error: oldString пуст"
        val text = f.readText(Charsets.UTF_8)
        val count = countOccurrences(text, old)
        if (count == 0) return "error: oldString не найден в файле"
        if (count > 1 && !args.optBoolean("replaceAll", false)) {
            return "error: oldString встречается $count раз — уточните текст или передайте replaceAll: true"
        }
        val updated = if (args.optBoolean("replaceAll", false)) text.replace(old, new) else text.replaceFirst(old, new)
        f.writeText(updated, Charsets.UTF_8)
        return "ok: заменено вхождений: ${if (args.optBoolean("replaceAll", false)) count else 1}"
    }

    private fun doList(args: JSONObject): String {
        val path = args.optString("path", ".")
        val dir = resolve(path) ?: return "error: путь вне песочницы"
        if (!dir.exists()) return "error: нет такого каталога: $path"
        if (!dir.isDirectory) return "error: не каталог: $path"
        val entries = dir.listFiles()?.sortedWith(compareByDescending<File> { it.isDirectory }.thenBy { it.name }) ?: return "(empty)"
        if (entries.isEmpty()) return "(empty)"
        return entries.take(200).joinToString("\n") { f -> if (f.isDirectory) f.name + "/" else f.name + " (${f.length()} bytes)" }
    }

    private fun doGlob(args: JSONObject): String {
        val pattern = args.getString("pattern")
        val dir = resolve(args.optString("path", ".")) ?: return "error: путь вне песочницы"
        val base = dir.takeIf { it.isDirectory } ?: workspace.root
        val matches = mutableListOf<File>()
        base.walkTopDown().forEach { f ->
            if (f.isFile) {
                val rel = f.relativeToOrNull(base)?.path ?: return@forEach
                if (globToRegex(pattern).matches(rel)) matches += f
            }
        }
        if (matches.isEmpty()) return "(нет совпадений)"
        return matches.sortedByDescending { it.lastModified() }
            .take(200)
            .joinToString("\n") { workspace.relativeTo(it) }
    }

    private fun doGrep(args: JSONObject): String {
        val pattern = try { Regex(args.getString("pattern")) } catch (t: Throwable) { return "error: плохой regex: ${t.message}" }
        val dir = resolve(args.optString("path", ".")) ?: return "error: путь вне песочницы"
        val base = dir.takeIf { it.isDirectory } ?: workspace.root
        val include = args.optString("include").takeIf { it.isNotBlank() }?.let { globToRegex(it) }
        val out = StringBuilder()
        base.walkTopDown().forEach { f ->
            if (out.length > MAX_TOOL_OUTPUT) return@forEach
            if (!f.isFile || f.length() > 512 * 1024) return@forEach
            val rel = workspace.relativeTo(f)
            if (include != null && !include.matches(f.name) && !include.matches(rel)) return@forEach
            val text = runCatching { f.readText(Charsets.UTF_8) }.getOrNull() ?: return@forEach
            text.lines().forEachIndexed { idx, line ->
                if (pattern.containsMatchIn(line)) out.append("$rel:${idx + 1}: ${line.take(300)}\n")
            }
        }
        return out.toString().trim().take(MAX_TOOL_OUTPUT).ifEmpty { "(нет совпадений)" }
    }

    private fun doApplyPatch(args: JSONObject): String {
        return try {
            val result = ApplyPatch.apply(args.getString("patchText")) { path -> resolve(path) }
            buildString {
                if (result.applied.isNotEmpty()) appendLine(result.applied.joinToString("\n"))
                if (result.skipped.isNotEmpty()) appendLine("skipped: " + result.skipped.joinToString("; "))
            }.trim().ifEmpty { "патч не содержал операций" }
        } catch (e: ApplyPatch.PatchException) {
            "error: ${e.message}"
        }
    }

    private fun doTodoWrite(args: JSONObject): String {
        val arr = args.optJSONArray("todos") ?: return "error: нужен массив todos"
        val list = mutableListOf<Sessions.Todo>()
        for (i in 0 until arr.length()) {
            val o = arr.optJSONObject(i) ?: continue
            val content = o.optString("content")
            if (content.isEmpty()) continue
            val status = o.optString("status", "pending")
            list += Sessions.Todo(
                id = o.optString("id").ifEmpty { "t$i" },
                content = content,
                status = if (status in listOf("pending", "in_progress", "completed")) status else "pending",
            )
        }
        todos = list
        onTodos?.invoke(list)
        return "todos updated: ${list.size}"
    }

    private fun doWebFetch(args: JSONObject): String {
        val url = args.getString("url")
        if (!url.startsWith("http://") && !url.startsWith("https://")) return "error: только http(s) URL"
        return try {
            val conn = URL(url).openConnection() as HttpURLConnection
            conn.connectTimeout = 10_000
            conn.readTimeout = 30_000
            conn.instanceFollowRedirects = true
            conn.setRequestProperty("User-Agent", "Mozilla/5.0 (compatible; PocketRunAgent/1.3)")
            val status = conn.responseCode
            val body = (if (status in 200..299) conn.inputStream else conn.errorStream)
                ?.bufferedReader(Charsets.UTF_8)?.use { it.readText() } ?: ""
            if (status !in 200..299) return "HTTP $status: ${body.take(300)}"
            val text = stripHtml(body)
            text.take(MAX_WEB).ifEmpty { "(пустой ответ)" }
        } catch (t: Throwable) {
            "error: ${t.message ?: t.javaClass.simpleName}"
        }
    }

    private fun doSkill(args: JSONObject): String {
        val name = args.getString("name")
        val skill = skills.load(name, projectDir)
            ?: return "error: навык '$name' не найден. Доступны: ${skills.discover(projectDir).joinToString(", ") { it.name }.ifEmpty { "(нет)" }}"
        return skill.content.take(32 * 1024)
    }

    private fun doQuestion(args: JSONObject): String {
        val arr = args.optJSONArray("questions") ?: return "error: нужен массив questions"
        val questions = mutableListOf<Question>()
        for (i in 0 until arr.length()) {
            val o = arr.optJSONObject(i) ?: continue
            val opts = o.optJSONArray("options") ?: JSONArray()
            questions += Question(
                header = o.optString("header").takeIf { it.isNotEmpty() },
                question = o.optString("question").ifEmpty { "Вопрос" },
                options = (0 until opts.length()).map { opts.optString(it) },
            )
        }
        if (questions.isEmpty()) return "error: нет вопросов"
        val asker = questionAsker ?: return "(вопросы недоступны в этом режиме)"
        return asker(questions)
    }

    private fun doGitHub(args: JSONObject): String {
        if (githubToken.isBlank()) {
            return "error: GitHub-токен не задан — откройте ⚙ → GitHub и вставьте PAT (scopes repo, workflow)"
        }
        val gh = GitHubClient(githubToken)
        val op = args.optString("op")
        return try {
            when (op) {
                "me" -> gh.me()
                "repo_list" -> gh.repoList()
                "repo_create" -> gh.repoCreate(
                    name = args.getString("name"),
                    private = args.optBoolean("private", true),
                    description = args.optString("description").takeIf { it.isNotEmpty() },
                )
                "push" -> {
                    val arr = args.optJSONArray("files") ?: return "error: нужен массив files[{path,content}]"
                    val files = mutableListOf<Pair<String, String>>()
                    for (i in 0 until arr.length()) {
                        val f = arr.optJSONObject(i) ?: continue
                        val p = f.optString("path")
                        if (p.isNotEmpty()) files += p to f.optString("content")
                    }
                    if (files.isEmpty()) return "error: files пуст"
                    gh.pushFiles(args.getString("repo"), files, args.optString("message", "update"), args.optString("branch").takeIf { it.isNotEmpty() })
                }
                "file_get" -> gh.fileGet(args.getString("repo"), args.getString("path"), args.optString("ref").takeIf { it.isNotEmpty() })
                "workflow_create" -> gh.workflowCreate(args.getString("repo"), args.optString("filename", "run.yml"), args.getString("yaml"))
                "dispatch" -> gh.dispatch(args.getString("repo"), args.getString("workflow"), args.optString("ref").takeIf { it.isNotEmpty() })
                "runs" -> gh.runs(args.getString("repo"), args.optInt("limit", 10))
                "logs" -> gh.logs(args.getString("repo"), args.getLong("run_id"))
                "artifacts" -> gh.artifacts(args.getString("repo"), args.optLong("run_id", 0).takeIf { it != 0L })
                "artifact_download" -> gh.artifactDownload(args.getString("repo"), args.getLong("artifact_id"))
                "api" -> gh.api(args.optString("method", "GET"), args.getString("api_path"), args.optString("body").takeIf { it.isNotEmpty() })
                else -> "error: неизвестная операция '$op' (me, repo_list, repo_create, push, file_get, workflow_create, dispatch, runs, logs, artifacts, artifact_download, api)"
            }
        } catch (e: GitHubClient.GitHubException) {
            "error: ${e.message}"
        }
    }

    // ---------------------------------------------------------------- helpers

    private fun resolve(path: String): File? = workspace.resolve(path, base())

    private fun countOccurrences(text: String, needle: String): Int {
        var count = 0
        var idx = 0
        while (true) {
            idx = text.indexOf(needle, idx)
            if (idx < 0) return count
            count++
            idx += needle.length
        }
    }

    private fun globToRegex(pattern: String): Regex {
        val regex = buildString {
            append('^')
            var i = 0
            while (i < pattern.length) {
                when (val c = pattern[i]) {
                    '*' -> if (i + 1 < pattern.length && pattern[i + 1] == '*') { append(".*"); i++ } else append("[^/]*")
                    '?' -> append('.')
                    else -> if (c in "\\^$.|+()[]{}") { append('\\'); append(c) } else append(c)
                }
                i++
            }
            append('$')
        }
        return Regex(regex)
    }

    private fun stripHtml(html: String): String {
        return html
            .replace(Regex("(?is)<(script|style)[^>]*>.*?</\\1>"), " ")
            .replace(Regex("(?s)<!--.*?-->"), " ")
            .replace(Regex("(?s)<br[^>]*>|</p>|</div>|</li>"), "\n")
            .replace(Regex("(?s)<[^>]+>"), " ")
            .replace("&nbsp;", " ").replace("&amp;", "&").replace("&lt;", "<")
            .replace("&gt;", ">").replace("&quot;", "\"").replace("&#39;", "'")
            .replace(Regex("[ \\t\\x0B\\f\\r]+"), " ")
            .replace(Regex("\\n\\s*\\n+"), "\n")
            .trim()
    }
}

