                val step = maxSteps - budget
                onEvent(Event.Round(step, maxSteps))

                val response = try {
                    val request = HistoryTrimmer.trim(full, maxHistoryChars)
                    clientFactory().chat(request, tools.definitions(), isCancelled) { delta -> preview.append(delta) ... }
