package dev.pocketrun.agent

import com.sun.net.httpserver.HttpServer
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.net.InetSocketAddress
import java.util.ArrayDeque
import java.util.concurrent.Executors

/**
 * The chat client against a local OpenAI-compatible server: SSE streams
 * (including tool calls that arrive in pieces), plain JSON answers from servers
 * that ignore `stream`, an empty stream that must fall back to a plain request,
 * cancellation between chunks and errors that must not kill the turn silently.
 */
class LlmClientTest {

    private class Resp(val contentType: String, val body: String, val status: Int = 200)

    private fun client(port: Int) = LlmClient(AgentSettings.Config("http://127.0.0.1:$port/v1", "", "test-model"))

    private fun messages(text: String = "привет") = JSONArray()
        .put(JSONObject().put("role", "system").put("content", "system"))
        .put(JSONObject().put("role", "user").put("content", text))

    /** Serves [responses] in order; the last one repeats when the queue runs dry. */
    private fun serve(responses: List<Resp>): Pair<Int, () -> Unit> {
        val server = HttpServer.create(InetSocketAddress("127.0.0.1", 0), 0)
        val queue = ArrayDeque(responses)
        server.createContext("/v1/chat/completions") { exchange ->
            exchange.requestBody.use { it.readBytes() }
            val resp = synchronized(queue) { if (queue.size > 1) queue.removeFirst() else queue.first() }
            val bytes = resp.body.toByteArray(Charsets.UTF_8)
            exchange.responseHeaders.add("Content-Type", resp.contentType)
            if (resp.status == 401) {
                exchange.sendResponseHeaders(resp.status, -1)
                exchange.close()
                return@createContext
            }
            exchange.sendResponseHeaders(resp.status, bytes.size.toLong())
            exchange.responseBody.use { it.write(bytes) }
        }
        server.executor = Executors.newSingleThreadExecutor { r -> Thread(r, "fake-llm").apply { isDaemon = true } }
        server.start()
        return server.address.port to { server.stop(0) }
    }

    private fun sse(vararg chunks: JSONObject): String =
        chunks.joinToString("") { "data: $it\n\n" } + "data: [DONE]\n\n"

    private fun delta(content: String) = JSONObject()
        .put("choices", JSONArray().put(JSONObject().put("index", 0).put("delta", JSONObject().put("content", content))))

    private fun toolDelta(index: Int, id: String?, name: String?, args: String?) = JSONObject().put(
        "choices",
        JSONArray().put(
            JSONObject().put(
                "index", 0,
                "delta", JSONObject().put(
                    "tool_calls",
                    JSONArray().put(
                        JSONObject().put("index", index).apply {
                            if (id != null) put("id", id)
                            put(
                                "function",
                                JSONObject().apply {
                                    if (name != null) put("name", name)
                                    if (args != null) put("arguments", args)
                                },
                            )
                        },
                    ),
                ),
            ),
        ),
    )

    @Test
    fun plainJsonAnswerIsParsed() {
        val (port, stop) = serve(
            listOf(Resp("application/json", """{"choices":[{"message":{"role":"assistant","content":"обычный ответ"}}]}""")),
        )
        try {
            val r = client(port).chat(messages(), null)
            assertEquals("обычный ответ", r.content)
            assertTrue(r.toolCalls.isEmpty())
        } finally {
            stop()
        }
    }

    @Test
    fun sseTextAndToolCallsAreAssembled() {
        val (port, stop) = serve(
            listOf(
                Resp(
                    "text/event-stream",
                    sse(
                        delta("При"),
                        delta("вет, "),
                        delta("всё сделано."),
                        toolDelta(0, "call_1", "bash", """{"command":""""),
                        toolDelta(0, null, null, """echo hi"}"""),
                    ),
                ),
            ),
        )
        try {
            val r = client(port).chat(messages(), null)
            assertEquals("Привет, всё сделано.", r.content)
            assertEquals(1, r.toolCalls.size)
            assertEquals("call_1", r.toolCalls[0].id)
            assertEquals("bash", r.toolCalls[0].name)
            assertEquals("""{"command":"echo hi"}""", r.toolCalls[0].arguments)
        } finally {
            stop()
        }
    }

    @Test
    fun parallelToolCallsKeepTheirOrder() {
        val (port, stop) = serve(
            listOf(
                Resp(
                    "text/event-stream",
                    sse(
                        toolDelta(0, "a", "read", """{"filePath":"a.txt"}"""),
                        toolDelta(1, "b", "read", """{"filePath":"b.txt"}"""),
                    ),
                ),
            ),
        )
        try {
            val r = client(port).chat(messages(), null)
            assertEquals(listOf("a", "b"), r.toolCalls.map { it.id })
            assertEquals(listOf("read", "read"), r.toolCalls.map { it.name })
        } finally {
            stop()
        }
    }

    @Test
    fun emptyStreamFallsBackToAPlainRequest() {
        val (port, stop) = serve(
            listOf(
                Resp("text/event-stream", "data: [DONE]\n\n"),
                Resp("application/json", """{"choices":[{"message":{"content":"со второго раза"}}]}"""),
            ),
        )
        try {
            assertEquals("со второго раза", client(port).chat(messages(), null).content)
        } finally {
            stop()
        }
    }

    @Test
    fun errorInsideTheStreamIsReported() {
        val err = JSONObject().put("error", JSONObject().put("message", "model is overloaded"))
        val (port, stop) = serve(listOf(Resp("text/event-stream", sse(err))))
        try {
            client(port).chat(messages(), null)
            fail("ожидалась ошибка модели")
        } catch (e: LlmClient.LlmException) {
            assertTrue(e.message.orEmpty(), e.message.orEmpty().contains("model is overloaded"))
        } finally {
            stop()
        }
    }

    @Test
    fun reasoningOnlyAnswerBecomesContent() {
        val chunk = JSONObject().put(
            "choices",
            JSONArray().put(
                JSONObject().put("index", 0).put("delta", JSONObject().put("reasoning_content", "думаю…")),
            ),
        )
        val (port, stop) = serve(listOf(Resp("text/event-stream", sse(chunk))))
        try {
            assertEquals("думаю…", client(port).chat(messages(), null).content)
        } finally {
            stop()
        }
    }

    @Test
    fun cancellationBeforeTheRequestDoesNothing() {
        val (port, stop) = serve(listOf(Resp("text/event-stream", sse(delta("неважно")))))
        try {
            val e = runCatching { client(port).chat(messages(), null, isCancelled = { true }) }.exceptionOrNull()
            assertTrue("ожидалась отмена, а получили $e", e is LlmClient.LlmException)
            assertEquals(LlmClient.CANCELLED, e?.message)
        } finally {
            stop()
        }
    }

    @Test
    fun cancellationBetweenChunksStopsTheStream() {
        // The server keeps the stream open long after the client gave up.
        val server = HttpServer.create(InetSocketAddress("127.0.0.1", 0), 0)
        server.createContext("/v1/chat/completions") { exchange ->
            exchange.requestBody.use { it.readBytes() }
            exchange.responseHeaders.add("Content-Type", "text/event-stream")
            exchange.sendResponseHeaders(200, 0) // chunked
            exchange.responseBody.use { out ->
                out.write("data: ${delta("начало")}\n\n".toByteArray())
                out.flush()
                Thread.sleep(1_000)
                runCatching { out.write("data: [DONE]\n\n".toByteArray()) }
            }
        }
        server.executor = Executors.newSingleThreadExecutor { r -> Thread(r, "fake-llm-slow").apply { isDaemon = true } }
        server.start()
        try {
            var seen = 0
            val e = runCatching {
                client(server.address.port).chat(messages(), null, isCancelled = { seen > 0 }) { seen++ }
            }.exceptionOrNull()
            assertTrue("ожидалась отмена, а получили $e", e is LlmClient.LlmException)
            assertEquals(LlmClient.CANCELLED, e?.message)
            assertEquals(1, seen)
        } finally {
            server.stop(0)
        }
    }

    @Test
    fun rejectedKeyIsNotRetriedAndNamesTheStatus() {
        val (port, stop) = serve(listOf(Resp("application/json", """{"error":{"message":"bad key"}}""", status = 401)))
        try {
            val e = runCatching { client(port).chat(messages(), null) }.exceptionOrNull()
            assertTrue("$e", e is LlmClient.LlmException)
            assertTrue(e!!.message.orEmpty(), e.message.orEmpty().contains("401"))
        } finally {
            stop()
        }
    }
}

package dev.pocketrun.agent.opencode

import com.sun.net.httpserver.HttpServer
import dev.pocketrun.agent.AgentSettings
import dev.pocketrun.agent.LlmClient
import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.js.JsRuntime
import dev.pocketrun.runtime.npm.NpxRuntime
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.File
import java.net.InetSocketAddress
import java.util.ArrayDeque
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * The agent loop against a local OpenAI-compatible server: tool calls run and
 * come back, the round budget stops a runaway turn, and an interrupted turn
 * still leaves a history that the next request can be built on (every tool call
 * answered — a half-answered one is rejected by strict providers).
 */
class OpenCodeAgentTest {

    @get:Rule
    val tmp = TemporaryFolder()

    private fun bootSource(): String = listOf(
        File("src/main/assets/node/boot.js"),
        File("app/src/main/assets/node/boot.js"),
    ).firstOrNull { it.isFile }?.readText(Charsets.UTF_8) ?: error("boot.js not found")

    private fun chunk(delta: JSONObject) = JSONObject()
        .put("choices", JSONArray().put(JSONObject().put("index", 0).put("delta", delta)))

    private fun toolChunk(id: String, name: String, args: String) = chunk(
        JSONObject().put(
            "tool_calls",
            JSONArray().put(
                JSONObject().put("index", 0).put("id", id).put("type", "function")
                    .put("function", JSONObject().put("name", name).put("arguments", args)),
            ),
        ),
    )

    private fun sse(vararg chunks: JSONObject) =
        chunks.joinToString("") { "data: $it\n\n" } + "data: [DONE]\n\n"

    /** Serves [responses] in order; the last one repeats when the queue runs dry. */
    private fun serve(responses: List<String>): Pair<Int, () -> Unit> {
        val server = HttpServer.create(InetSocketAddress("127.0.0.1", 0), 0)
        val queue = ArrayDeque(responses)
        server.createContext("/v1/chat/completions") { exchange ->
            exchange.requestBody.use { it.readBytes() }
            val body = synchronized(queue) { if (queue.size > 1) queue.removeFirst() else queue.first() }
            val bytes = body.toByteArray(Charsets.UTF_8)
            exchange.responseHeaders.add("Content-Type", "text/event-stream")
            exchange.sendResponseHeaders(200, bytes.size.toLong())
            exchange.responseBody.use { it.write(bytes) }
        }
        server.executor = Executors.newSingleThreadExecutor { r -> Thread(r, "fake-llm").apply { isDaemon = true } }
        server.start()
        return server.address.port to { server.stop(0) }
    }

    private fun projectDir(): File {
        val ws = Workspace.at(tmp.newFolder())
        val project = File(ws.root, "proj").apply { mkdirs() }
        val js = JsRuntime(bootSource(), ws, maxRunMs = 10_000)
        tools = OpenCodeTools(ws, js, NpxRuntime(js, ws), project, "")
        return project
    }

    private lateinit var tools: OpenCodeTools

    private fun agent(port: Int, maxSteps: Int, cancelled: () -> Boolean = { false }): OpenCodeAgent {
        val config = AgentSettings.Config("http://127.0.0.1:$port/v1", "", "test-model")
        return OpenCodeAgent(
            tools.workspace, tools, { LlmClient(config) }, tools.projectDirForTest,
            maxSteps = maxSteps, isCancelled = cancelled,
        )
    }

    /** Every tool call in the history must be answered by a tool message. */
    private fun assertValidHistory(history: JSONArray) {
        val pending = mutableSetOf<String>()
        for (i in 0 until history.length()) {
            val m = history.getJSONObject(i)
            when (m.optString("role")) {
                "assistant" -> m.optJSONArray("tool_calls")?.let { calls ->
                    for (c in 0 until calls.length()) pending.add(calls.getJSONObject(c).optString("id"))
                }
                "tool" -> assertTrue(
                    "tool_call ${m.optString("tool_call_id")} без соответствующего вызова",
                    pending.remove(m.optString("tool_call_id")),
                )
                "user" -> assertTrue("user посреди неотвеченных вызовов", pending.isEmpty())
            }
        }
    }

    @Test
    fun toolCallIsExecutedAndTheAnswerEndsTheTurn() {
        val project = projectDir()
        val (port, stop) = serve(
            listOf(
                sse(toolChunk("c1", "write", """{"filePath":"note.txt","content":"привет из агента"}""")),
                sse(chunk(JSONObject().put("content", "Готово, файл записан"))),
            ),
        )
        val events = mutableListOf<OpenCodeAgent.Event>()
        try {
            val history = agent(port, maxSteps = 5).run("создай файл", JSONArray()) { events += it }
            assertEquals("привет из агента", File(project, "note.txt").readText())
            assertTrue(events.any { it is OpenCodeAgent.Event.ToolStart && it.name == "write" })
            assertTrue(events.any { it is OpenCodeAgent.Event.AssistantText && it.text.contains("Готово") })
            assertTrue(events.none { it is OpenCodeAgent.Event.Failed })
            assertEquals("Готово, файл записан", history.getJSONObject(history.length() - 1).optString("content"))
            assertValidHistory(history)
        } finally {
            stop()
        }
    }

    @Test
    fun roundBudgetStopsARunawayTurnAndKeepsTheHistoryValid() {
        projectDir()
        val write = sse(toolChunk("c1", "write", """{"filePath":"loop.txt","content":"x"}"""))
        val (port, stop) = serve(listOf(write))
        val events = mutableListOf<OpenCodeAgent.Event>()
        try {
            val history = agent(port, maxSteps = 3).run("зациклись", JSONArray()) { events += it }
            val writes = events.count { it is OpenCodeAgent.Event.ToolStart }
            assertEquals(3, writes)
            val failure = events.filterIsInstance<OpenCodeAgent.Event.Failed>().lastOrNull()
            assertTrue(failure?.message.orEmpty(), failure?.message.orEmpty().contains("достигнут лимит раундов (3)"))
            assertValidHistory(history)
        } finally {
            stop()
        }
    }

    @Test
    fun interruptedTurnAnswersEveryToolCall() {
        val project = projectDir()
        val (port, stop) = serve(
            listOf(sse(toolChunk("c1", "write", """{"filePath":"one.txt","content":"1"}"""))),
        )
        val cancelled = AtomicBoolean(false)
        val events = mutableListOf<OpenCodeAgent.Event>()
        try {
            val history = agent(port, maxSteps = 10, cancelled = { cancelled.get() }).run("пиши", JSONArray()) { event ->
                events += event
                if (event is OpenCodeAgent.Event.ToolDone) cancelled.set(true)
            }
            assertTrue(File(project, "one.txt").isFile)
            assertTrue(events.filterIsInstance<OpenCodeAgent.Event.Failed>().last().message.contains("остановлено"))
            // The second round's call never ran, but the saved history must not
            // keep a tool call without an answer.
            assertValidHistory(history)
            val last = history.getJSONObject(history.length() - 1)
            assertEquals("tool", last.optString("role"))
            assertTrue(last.optString("content"), last.optString("content").contains("прервано"))
        } finally {
            stop()
        }
    }

    @Test
    fun emptyAnswerIsNudgedInsteadOfEndingTheTurnInSilence() {
        projectDir()
        val (port, stop) = serve(
            listOf(
                "data: [DONE]\n\n",
                sse(chunk(JSONObject().put("content", "теперь отвечаю"))),
            ),
        )
        val events = mutableListOf<OpenCodeAgent.Event>()
        try {
            val history = agent(port, maxSteps = 3).run("?", JSONArray()) { events += it }
            assertTrue(events.any { it is OpenCodeAgent.Event.AssistantText && it.text.contains("теперь отвечаю") })
            assertTrue(events.none { it is OpenCodeAgent.Event.Failed })
            assertValidHistory(history)
        } finally {
            stop()
        }
    }

    @Test
    fun longHistoryIsTrimmedButTheRequestStaysValid() {
        val project = projectDir()
        val (port, stop) = serve(
            listOf(
                sse(toolChunk("c1", "write", """{"filePath":"big.txt","content":"x"}""")),
                sse(chunk(JSONObject().put("content", "сделано"))),
            ),
        )
        // A history of fat tool results: the agent must shrink it to stay in context.
        val history = JSONArray()
            .put(JSONObject().put("role", "user").put("content", "исходная задача"))
        repeat(30) { i ->
            history.put(
                JSONObject()
                    .put("role", "assistant")
                    .put(
                        "tool_calls",
                        JSONArray().put(
                            JSONObject().put("id", "old$i").put("type", "function")
                                .put("function", JSONObject().put("name", "read").put("arguments", """{"filePath":"f$i"}""")),
                        ),
                    ),
            )
            history.put(
                JSONObject().put("role", "tool").put("tool_call_id", "old$i")
                    .put("content", "вывод ".repeat(2_000) + i),
            )
        }
        val seen = mutableListOf<Int>()
        try {
            val result = agent(port, maxSteps = 4).run("продолжай", history) { seen += 1 }
            assertTrue(seen.isNotEmpty())
            assertValidHistory(result)
            assertTrue("исходная задача не потеряна", result.optJSONObject(0)?.optString("content") == "исходная задача")
            assertTrue(File(project, "big.txt").isFile)
        } finally {
            stop()
        }
    }
}

